<?php require __DIR__.'/../includes/core.php';require_login(['admin','management']);$deleteError='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();
 if(me()['role']!=='admin'){http_response_code(403);exit('Admin access required');}
 try {
  $action=(string)($_POST['action']??'');$id=(int)($_POST['assignment_id']??0);
  if(in_array($action,['reset_evaluation','delete_evaluation'],true)){
   if(empty($_POST['report_saved'])||($_POST['confirm_word']??'')!==($action==='reset_evaluation'?'RESET':'DELETE')) throw new Exception('Download the report and enter the confirmation word before proceeding.');
   $a=one("SELECT a.*,m.name module_name FROM assignments a JOIN modules m ON m.id=a.module_id WHERE a.id=? AND a.status='submitted'",[$id]);
   if(!$a)throw new Exception('Submitted evaluation not found.');
   $archive=['action'=>$action,'assignment'=>$a,'responses'=>all('SELECT * FROM responses WHERE assignment_id=?',[$id]),'comments'=>all('SELECT * FROM evaluation_comments WHERE assignment_id=?',[$id]),'external_remarks'=>all('SELECT * FROM evaluation_external_remarks WHERE assignment_id=?',[$id])];
   $db=db();$db->beginTransaction();try{
    sql('INSERT INTO evaluation_deletion_archive(assignment_id,teacher_id,module_name,deleted_by,snapshot_json) VALUES (?,?,?,?,?)',[$id,$a['subject_id'],$a['module_name'],me()['id'],json_encode($archive,JSON_THROW_ON_ERROR)]);
    sql('UPDATE evaluation_external_shares SET revoked_at=NOW() WHERE assignment_id=? AND revoked_at IS NULL',[$id]);
    sql('DELETE FROM responses WHERE assignment_id=?',[$id]);sql('DELETE FROM evaluation_comments WHERE assignment_id=?',[$id]);
    if($action==='reset_evaluation')sql("UPDATE assignments SET status='pending',submitted_at=NULL,observation_date=NULL,subject_name=NULL,class_name=NULL,period_name=NULL WHERE id=?",[$id]);
    else sql('DELETE FROM assignments WHERE id=?',[$id]);
    audit($action,'Assignment '.$id);$db->commit();
   }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
   flash($action==='reset_evaluation'?'Evaluation reset. The assigned evaluator can submit again.':'Evaluation deleted. A restricted audit snapshot was retained.');go('management/reports.php');
  }elseif($action==='create_share'){
   $a=one("SELECT id FROM assignments WHERE id=? AND status='submitted'",[$id]);if(!$a)throw new Exception('Submitted evaluation not found.');
   $token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);
   sql('INSERT INTO evaluation_external_shares(assignment_id,token_hash,created_by,expires_at) VALUES (?,?,?,DATE_ADD(NOW(),INTERVAL 7 DAY))',[$id,$hash,me()['id']]);
   audit('external_share_created','Assignment '.$id);
   $_SESSION['new_external_share']=['assignment_id'=>$id,'link'=>url('external/review.php?token='.$token)];go('management/reports.php');
  }elseif($action==='revoke_share'){
   $shareId=(int)($_POST['share_id']??0);
   sql('UPDATE evaluation_external_shares SET revoked_at=NOW() WHERE id=? AND created_by IS NOT NULL',[$shareId]);audit('external_share_revoked','Share '.$shareId);flash('External access revoked.');go('management/reports.php');
  }
 }catch(Throwable $e){$deleteError=$e->getMessage();}
}
$filter=(int)($_GET['teacher']??0);$teachers=all("SELECT id,name FROM users WHERE role='teacher' ORDER BY name");$query="SELECT a.id,a.status,a.submitted_at,m.name module_name,t.name teacher,e.name evaluator,s.name session_name,c.term FROM assignments a JOIN modules m ON m.id=a.module_id JOIN users t ON t.id=a.subject_id JOIN users e ON e.id=a.evaluator_id JOIN evaluation_cycles c ON c.id=a.cycle_id JOIN academic_sessions s ON s.id=c.session_id WHERE a.status='submitted'"; $params=[];if($filter){$query.=' AND t.id=?';$params[]=$filter;}$rows=all($query.' ORDER BY a.submitted_at DESC',$params);if(isset($_GET['csv'])){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="bgb_evaluation_results.csv"');$f=fopen('php://output','w');fputcsv($f,['Teacher','Module','Evaluator','Session','Term','Raw score','Maximum','Raw percentage','Weighted percentage','Submitted']);foreach($rows as $r){$sc=score_assignment($r['id']);fputcsv($f,[$r['teacher'],$r['module_name'],$r['evaluator'],$r['session_name'],$r['term'],$sc['raw'],$sc['max'],round($sc['raw_percent'],2),round($sc['weighted_percent'],2),$r['submitted_at']]);}exit;}$shares=all('SELECT es.id,es.assignment_id,es.expires_at,es.revoked_at,er.assessor_name,er.remarks,er.created_at remark_at FROM evaluation_external_shares es LEFT JOIN evaluation_external_remarks er ON er.share_id=es.id ORDER BY es.id DESC');$sharesByAssignment=[];foreach($shares as $share)$sharesByAssignment[$share['assignment_id']][]=$share;ob_start();if(!empty($_SESSION['new_external_share'])){$newShare=$_SESSION['new_external_share'];unset($_SESSION['new_external_share']);echo '<div class="card"><h3>External assessment link — copy now</h3><p>This private link is displayed once. It expires in 7 days. Anyone possessing it can view the assessment and leave one remark.</p><input readonly onclick="this.select()" value="'.h($newShare['link']).'"><p><a class="btn alt" href="'.h($newShare['link']).'" target="_blank" rel="noopener">Open link</a></p></div>';}if($deleteError)echo '<div class="alert error">'.h($deleteError).'</div>';?><div class="card"><h2>Central evaluation controls</h2><p>Manage evaluations in bulk by academic cycle and module, or create one external assessor link for all submitted assessments in the selected scope.</p><div class="actions"><a class="btn alt" href="<?=url('admin/bulk_evaluations.php')?>">Bulk reset / delete</a><a class="btn alt" href="<?=url('admin/external_access.php')?>">General external assessor link</a></div></div><div class="card"><form method="get"><label>Filter by teacher</label><select name="teacher"><option value="0">All teachers</option><?php foreach($teachers as $t)echo '<option value="'.$t['id'].'" '.($filter==$t['id']?'selected':'').'>'.h($t['name']).'</option>';?></select><div class="actions"><button>Filter</button><a class="btn alt" href="?teacher=<?=$filter?>&csv=1">Export CSV</a></div></form></div><div class="card"><h2>Confidential submitted results</h2><div class="tablewrap"><table><tr><th>Teacher</th><th>Module</th><th>Evaluator</th><th>Session / Term</th><th>Score</th><th>Report</th></tr><?php foreach($rows as $r){$sc=score_assignment($r['id']);echo '<tr><td>'.h($r['teacher']).'</td><td>'.h($r['module_name']).'</td><td>'.h($r['evaluator']).'</td><td>'.h($r['session_name'].' '.$r['term']).'</td><td>'.number_format($sc['weighted_percent'],1).'%</td><td><a class="btn alt" href="'.url('management/report.php?id='.$r['id']).'">View / Save PDF</a>';if(me()['role']==='admin'){
 echo '<details><summary>Reset / Delete evaluation</summary><p><strong>Warning:</strong> Download the PDF first. Reset clears all grades and remarks, and reopens the same assignment; Delete removes the assignment. Both actions remove the previous assessment from live results, revoke external links, and preserve a restricted audit snapshot.</p>';
 foreach(['reset_evaluation'=>'RESET','delete_evaluation'=>'DELETE'] as $action=>$word){echo '<form method="post" onsubmit="return confirm(\'This will remove the existing evaluation data. Continue?\')">'.token().'<input type="hidden" name="action" value="'.$action.'"><input type="hidden" name="assignment_id" value="'.(int)$r['id'].'"><label><input type="checkbox" name="report_saved" value="1" required> I have downloaded and safely saved the report</label><label>Type '.$word.' to confirm</label><input name="confirm_word" required pattern="'.$word.'" placeholder="'.$word.'"><p><button type="submit">'.($action==='reset_evaluation'?'Reset for new submission':'Delete evaluation').'</button></p></form>';}echo '</details>';
 echo '<details><summary>External assessor link</summary><p>Create a private, expiring 7-day link for this specific submitted assessment. The assessor can view the report and leave one written remark.</p><form method="post">'.token().'<input type="hidden" name="action" value="create_share"><input type="hidden" name="assignment_id" value="'.(int)$r['id'].'"><button>Create external review link</button></form>';
 foreach($sharesByAssignment[$r['id']]??[] as $share){echo '<p class="small">Share #'.(int)$share['id'].' — expires '.h($share['expires_at']).($share['revoked_at']?' (revoked)':'').'</p>';if($share['remark_at'])echo '<p><strong>External remark by '.h($share['assessor_name']).':</strong> '.nl2br(h($share['remarks'])).'</p>';if(!$share['revoked_at'])echo '<form method="post">'.token().'<input type="hidden" name="action" value="revoke_share"><input type="hidden" name="share_id" value="'.(int)$share['id'].'"><button>Revoke access</button></form>';}echo '</details>';
 }
 echo '</td></tr>';}?></table></div></div><?php layout('Confidential evaluation results',ob_get_clean());